    function getSwipeExtra(message, swipeId, create) {
        if (!message) return null;
        if (!Array.isArray(message.swipe_info)) {
            if (!create) return null;
            message.swipe_info = [];
        }
        if (create) {
            while (message.swipe_info.length <= swipeId) message.swipe_info.push({});
        }
        const swipeInfo = message.swipe_info[swipeId];
        if (!swipeInfo || typeof swipeInfo !== 'object') {
            if (!create) return null;
            message.swipe_info[swipeId] = {};
        }
        const current = message.swipe_info[swipeId];
        if (!current.extra || typeof current.extra !== 'object' || Array.isArray(current.extra)) {
            if (!create) return null;
            current.extra = {};
        }
        return current.extra;
    }

    function saveChat(state) {
        const current = getState();
        if (state.chat !== current.chat || (state.chatId && current.chatId && state.chatId !== current.chatId)) return;
        const save = (ST && ST.saveChat) || (current.context && current.context.saveChat);
        if (typeof save !== 'function') return;
        try {
            const result = save.call(ST);
            if (result && typeof result.catch === 'function') {
                result.catch(function (error) {
                    console.warn('[SL 滚动记忆] 保存聊天元数据失败，当前会话仍可使用：', error);
                });
            }
        } catch (error) {
            console.warn('[SL 滚动记忆] 保存聊天元数据失败，当前会话仍可使用：', error);
        }
    }

    function processMessage(messageId, shouldSave) {
        const state = getState();
        const index = Number(messageId);
        const message = Number.isInteger(index) && state.chat[index]
            ? state.chat[index]
            : state.chat[state.chat.length - 1];
        if (!message || message.is_user || message.is_system) return false;

        const swipeId = getSwipeId(message);
        const original = getActiveText(message, swipeId);
        const update = extractUpdate(original);
        if (!update) return false;

        const extra = getSwipeExtra(message, swipeId, true);
        extra[SEED_META_KEY] = {
            version: 1,
            seed: update.seed,
            bodyHash: hashText(update.cleaned),
        };

        if (typeof message.mes === 'string') message.mes = update.cleaned;
        if (Array.isArray(message.swipes) && message.swipes[swipeId] === original) {
            message.swipes[swipeId] = update.cleaned;
        }

        if (shouldSave !== false) saveChat(state);
        return true;
    }

    function processCurrentChat() {
        const state = getState();
        let changed = false;
        for (let i = 0; i < state.chat.length; i++) {
            if (processMessage(i, false)) changed = true;
        }
        if (changed) saveChat(state);
    }

    function seedFromMessage(message) {
        if (!message || message.is_user || message.is_system) return '';
        const swipeId = getSwipeId(message);
        const text = getActiveText(message, swipeId);
        const extra = getSwipeExtra(message, swipeId, false);
        const saved = extra && extra[SEED_META_KEY];
        if (saved && saved.version === 1 && saved.bodyHash === hashText(text)) {
            return normalizeSeed(saved.seed);
        }
        const unprocessed = extractUpdate(text);
        return unprocessed ? unprocessed.seed : '';
    }

    function renderMacro() {
        const state = getState();
        const seeds = [];
        for (const message of state.chat) {
            const seed = seedFromMessage(message);
            if (seed) seeds.push(seed);
        }
        const latest = seeds.slice(-10);
        const slots = Array(10).fill(EMPTY_LABEL);
        const start = 10 - latest.length;
        for (let i = 0; i < latest.length; i++) slots[start + i] = latest[i];
        return '<SL_10_SEEDS oldest_to_newest>\n' +
            slots.map(function (seed, index) {
                return String(index).padStart(2, '0') + ': ' + seed;
            }).join('\n') +
            '\n</SL_10_SEEDS>';
    }

    function getEventApi() {
        const context = getContext();
        const types = ST.eventTypes || ST.event_types || (context && (context.eventTypes || context.event_types)) || {};
        const source = ST.eventSource || (context && context.eventSource);
        return { types: types, source: source };
    }

    function listen(eventName, handler) {
        const api = getEventApi();
        const eventType = api.types[eventName];
        if (!eventType || !api.source || typeof api.source.on !== 'function') return;
        api.source.on(eventType, handler);
        listeners.push([api.source, eventType, handler]);
    }

    function onReceived(messageId, type) {
        const allowed = ['normal', 'regenerate', 'swipe', 'continue', 'append', 'appendFinal', 'first_message', 'extension', 'command'];
        if (type && allowed.indexOf(String(type)) < 0) return;
        processMessage(messageId, true);
    }

    function onSwiped(messageId) {
        const state = getState();
        const capturedChat = state.chat;
        const capturedChatId = state.chatId;
        setTimeout(function () {
            const current = getState();
            if (capturedChat !== current.chat || (capturedChatId && current.chatId && capturedChatId !== current.chatId)) return;
            processMessage(messageId, true);
        }, 0);
    }

    function onSwipeDeleted(data) {
        const messageId = data && typeof data === 'object' ? data.messageId : data;
        onSwiped(messageId);
    }

    function onChatChanged() {
        setTimeout(processCurrentChat, 0);
    }

    function dispose() {
        for (const item of listeners) {
            try { item[0].removeListener(item[1], item[2]); } catch (_) {}
        }
        listeners.length = 0;
        try { if (typeof ST.unregisterMacro === 'function') ST.unregisterMacro(MACRO_NAME); } catch (_) {}
        if (hostWindow[INSTANCE_KEY] && hostWindow[INSTANCE_KEY].dispose === dispose) delete hostWindow[INSTANCE_KEY];
    }

    try {
        if (typeof ST.unregisterMacro === 'function') ST.unregisterMacro(MACRO_NAME);
        if (typeof ST.registerMacro !== 'function') throw new Error('当前酒馆助手没有 registerMacro 接口');
        ST.registerMacro(MACRO_NAME, function () { return renderMacro(); }, '当前聊天最近 10 条记忆，按旧到新排列；会跟随当前选中的 swipe。');
        listen('MESSAGE_RECEIVED', onReceived);
        listen('MESSAGE_SWIPED', onSwiped);
        listen('MESSAGE_SWIPE_DELETED', onSwipeDeleted);
        listen('MESSAGE_EDITED', onSwiped);
        listen('MESSAGE_UPDATED', onSwiped);
        listen('CHAT_CHANGED', onChatChanged);
        hostWindow[INSTANCE_KEY] = { dispose: dispose, render: renderMacro };
        if (typeof window.addEventListener === 'function') window.addEventListener('pagehide', dispose, { once: true });
        setTimeout(processCurrentChat, 0);
        console.info('[SL 滚动记忆] 已注册 {{sl_seeds}}；每聊天、每 swipe 独立读取。');
    } catch (error) {
        dispose();
        console.error('[SL 滚动记忆] 初始化失败：', error);
    }
})();
